import Foundation

// GENERATED from Wrapper/aiswitch-wrapper.sh and Wrapper/aiswitch-statusline.sh by Scripts/sync-embedded-scripts.py.
// Do not edit by hand; a unit test asserts these strings equal the files in the repository.
public enum EmbeddedScripts {
    public static let wrapperVersion = 1

    public static let wrapper = ##"""
#!/bin/sh
# aiswitch-wrapper.sh -- routes `claude` / `codex` to the account profile selected in AI Account Switcher.
#
# Installed as $AISWITCH_HOME/bin/claude and $AISWITCH_HOME/bin/codex (identical copies; the tool name
# comes from the name this file was invoked as).
#
# Profile resolution order:
#   1. AISWITCH_CLAUDE_PROFILE / AISWITCH_CODEX_PROFILE   (per-terminal override, e.g. "Open Terminal with account")
#   2. $AISWITCH_HOME/state/active-<tool>                  (written atomically by the app or `aiswitch use`)
#   3. "default"                                           (the CLI's own ~/.claude or ~/.codex login; no env change)
#
# A managed profile is applied by exporting exactly one variable: CLAUDE_CONFIG_DIR (claude) or CODEX_HOME (codex).
# Working directory, arguments, stdin/stdout, signals and the exit code pass straight through (exec).
#
# Environment knobs:
#   AISWITCH_HOME=DIR              state root (default ~/.aiswitch)
#   AISWITCH_QUIET=1               suppress warnings
#   AISWITCH_DEBUG=1               print the resolution to stderr before exec
#   AISWITCH_PRINT_RESOLUTION=1    print the resolution as key=value lines and exit 0 WITHOUT running the CLI
#                                  (used by `aiswitch doctor` and the test-suite)
#
# This file is generated by AI Account Switcher; edits are overwritten on reinstall.
AISWITCH_WRAPPER_VERSION=1

if [ -z "${HOME:-}" ]; then
  printf 'aiswitch: HOME is not set\n' >&2
  exit 2
fi
AISWITCH_HOME="${AISWITCH_HOME:-$HOME/.aiswitch}"
bindir="$AISWITCH_HOME/bin"
tool=$(basename "$0")

warn() {
  [ -n "${AISWITCH_QUIET:-}" ] || printf 'aiswitch: %s\n' "$*" >&2
}

# Portable "realpath": realpath(1) (macOS 13+/Linux), then readlink -f (macOS 12.3+), else the input.
resolve_path() {
  if command -v realpath >/dev/null 2>&1; then
    _r=$(realpath "$1" 2>/dev/null) && [ -n "$_r" ] && { printf '%s\n' "$_r"; return 0; }
  fi
  _r=$(readlink -f "$1" 2>/dev/null) && [ -n "$_r" ] && { printf '%s\n' "$_r"; return 0; }
  printf '%s\n' "$1"
}

case "$tool" in
  claude)
    envvar=CLAUDE_CONFIG_DIR
    overrideenv=AISWITCH_CLAUDE_PROFILE
    apivars="ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLAUDE_CODE_USE_BEDROCK CLAUDE_CODE_USE_VERTEX CLAUDE_CODE_USE_FOUNDRY"
    ;;
  codex)
    envvar=CODEX_HOME
    overrideenv=AISWITCH_CODEX_PROFILE
    apivars="OPENAI_API_KEY CODEX_API_KEY CODEX_ACCESS_TOKEN"
    ;;
  *)
    printf 'aiswitch: this wrapper must be named claude or codex (invoked as "%s")\n' "$tool" >&2
    exit 2
    ;;
esac

# ---------------------------------------------------------------------------
# 1. Locate the real executable (never ourselves).
# ---------------------------------------------------------------------------
self=$(resolve_path "$0")
bindir_resolved=$(resolve_path "$bindir")
real=""
if [ -r "$AISWITCH_HOME/config/$tool.real" ]; then
  IFS= read -r real < "$AISWITCH_HOME/config/$tool.real" || :
fi
if [ -n "$real" ]; then
  if [ ! -x "$real" ] || [ -d "$real" ] || [ "$(resolve_path "$real")" = "$self" ]; then
    warn "recorded path for $tool ($real) is not usable; falling back to PATH lookup"
    real=""
  fi
fi
if [ -z "$real" ]; then
  save_ifs=$IFS
  IFS=:
  for d in $PATH; do
    IFS=$save_ifs
    [ -n "$d" ] || d=.
    cand="$d/$tool"
    if [ -x "$cand" ] && [ ! -d "$cand" ]; then
      if [ "$(resolve_path "$d")" != "$bindir_resolved" ] && [ "$(resolve_path "$cand")" != "$self" ]; then
        real=$cand
        break
      fi
    fi
    IFS=:
  done
  IFS=$save_ifs
fi
if [ -z "$real" ]; then
  warn "could not find the real '$tool' executable (not in PATH outside $bindir). Run 'aiswitch doctor' or reinstall $tool."
  exit 127
fi

# ---------------------------------------------------------------------------
# 2. Resolve the profile.
# ---------------------------------------------------------------------------
eval "profile=\${$overrideenv:-}"
profile_source=env
if [ -z "$profile" ]; then
  profile_source=state
  if [ -r "$AISWITCH_HOME/state/active-$tool" ]; then
    IFS= read -r profile < "$AISWITCH_HOME/state/active-$tool" || :
  fi
fi
case "$profile" in
  ""|default) profile=default; [ "$profile_source" = state ] && [ ! -r "$AISWITCH_HOME/state/active-$tool" ] && profile_source=default ;;
  *[!A-Za-z0-9._-]*|.*)
    warn "ignoring invalid profile id '$profile'; using the default $tool login"
    profile=default
    ;;
esac

config_dir=""
applied=default
if [ "$profile" != default ]; then
  dir="$AISWITCH_HOME/profiles/$tool/$profile"
  if [ ! -d "$dir" ]; then
    warn "profile '$profile' has no directory at $dir; using the default $tool login"
    profile=default
  else
    eval "current=\${$envvar:-}"
    if [ -n "$current" ] && [ "$current" != "$dir" ]; then
      warn "$envvar is already set to '$current' in this shell; the aiswitch profile '$profile' is NOT applied (unset $envvar to use it)"
      applied=no
      config_dir=$current
    else
      export "$envvar=$dir"
      applied=yes
      config_dir=$dir
    fi
  fi
fi

# ---------------------------------------------------------------------------
# 3. Detect credentials in the environment that override the selected login.
# ---------------------------------------------------------------------------
overrides=""
for v in $apivars; do
  eval "val=\${$v:-}"
  if [ -n "$val" ]; then
    overrides="${overrides:+$overrides,}$v"
  fi
done
if [ -n "$overrides" ] && [ -z "${AISWITCH_NO_ENV_WARN:-}" ]; then
  warn "$overrides set in this shell; it takes precedence over the '$profile' $tool login (set AISWITCH_NO_ENV_WARN=1 to silence)"
fi

if [ -n "${AISWITCH_PRINT_RESOLUTION:-}" ] || [ -n "${AISWITCH_DEBUG:-}" ]; then
  out=/dev/stderr
  [ -n "${AISWITCH_PRINT_RESOLUTION:-}" ] && out=/dev/stdout
  {
    printf 'wrapper_version=%s\n' "$AISWITCH_WRAPPER_VERSION"
    printf 'tool=%s\n' "$tool"
    printf 'wrapper=%s\n' "$self"
    printf 'real=%s\n' "$real"
    printf 'real_resolved=%s\n' "$(resolve_path "$real")"
    printf 'profile=%s\n' "$profile"
    printf 'profile_source=%s\n' "$profile_source"
    printf 'env_var=%s\n' "$envvar"
    printf 'config_dir=%s\n' "$config_dir"
    printf 'applied=%s\n' "$applied"
    printf 'overrides=%s\n' "$overrides"
  } > "$out"
  [ -n "${AISWITCH_PRINT_RESOLUTION:-}" ] && exit 0
fi

exec "$real" "$@"
"""##

    public static let statusLine = ##"""
#!/bin/sh
# aiswitch-statusline.sh -- optional "usage beacon" for Claude Code status lines.
#
# Claude Code pipes a JSON document to the configured statusLine command on every update. For Pro/Max
# logins that JSON carries `rate_limits.five_hour` / `rate_limits.seven_day` (used_percentage, resets_at).
# This script stores that document (atomically) under $AISWITCH_HOME/usage/ so the app can show the latest
# values Claude Code itself observed, with no network call and no credential access. It then forwards the
# JSON to the status-line command that was configured before (if any) so your existing status line keeps working.
#
# Install per profile with the app (Settings > Usage beacon) or by setting in <profile>/settings.json:
#   "statusLine": { "type": "command", "command": "~/.aiswitch/bin/aiswitch-statusline" }
AISWITCH_HOME="${AISWITCH_HOME:-$HOME/.aiswitch}"
profile=default
case "${CLAUDE_CONFIG_DIR:-}" in
  "$AISWITCH_HOME"/profiles/claude/*) profile=${CLAUDE_CONFIG_DIR#"$AISWITCH_HOME"/profiles/claude/}; profile=${profile%%/*} ;;
esac
input=$(cat)
dir="$AISWITCH_HOME/usage"
mkdir -p "$dir" 2>/dev/null && chmod 700 "$dir" 2>/dev/null
tmp="$dir/.claude-$profile.statusline.$$"
if printf '%s\n' "$input" > "$tmp" 2>/dev/null; then
  chmod 600 "$tmp" 2>/dev/null
  mv -f "$tmp" "$dir/claude-$profile.statusline.json" 2>/dev/null || rm -f "$tmp"
fi
chain="$AISWITCH_HOME/config/statusline-chain-$profile"
if [ -r "$chain" ]; then
  IFS= read -r prev < "$chain" || prev=""
  if [ -n "$prev" ]; then
    printf '%s' "$input" | sh -c "$prev"
    exit $?
  fi
fi
exit 0
"""##
}
